initial begin
 repeat(20)@(negedge clk);@(posedge refclk);#0.001;base=cycle;rst=1;mission_start=1;
 $display("POR_RELEASE ticks=%0t cycle=%0d",$time,cycle);
 repeat(392)@(negedge clk);$display("OLD392_READY=%0b fault=%0b ticks=%0t",ready,fault,$time);
 repeat(700)@(negedge clk);$display("COLD_FINAL ready=%0b fault=%0b ticks=%0t",ready,fault,$time);
 mission_start=1;repeat(200)@(negedge clk);$display("COLD_MISSION_FINAL all=%0b ready=%0b fault=%0b",mission_all,ready,fault);
 mission_start=0;repeat(200)@(negedge clk);$display("WARM_HELD por=%0b pll=%0b all=%0b ready=%0b fault=%0b",rst,die.hub_C.w_pll_locked,mission_all,ready,fault);
 base=cycle;mission_start=1;$display("WARM_MISSION_RELEASE ticks=%0t",$time);
 repeat(392)@(negedge clk);$display("WARM392 all=%0b ready=%0b fault=%0b",mission_all,ready,fault);
 repeat(200)@(negedge clk);$display("WARM_FINAL all=%0b ready=%0b fault=%0b",mission_all,ready,fault);$finish;
end endmodule
module ot_die_start_reset_relay #(parameter bit EDGE_FALL=0)(input wire clk,d,output wire q);reg r0,r1;wire x;generate if(EDGE_FALL)begin reg rf;always @(negedge clk)rf<=d;assign x=rf;end else assign x=d;endgenerate always @(posedge clk)begin r0<=x;r1<=r0;end assign q=r1;endmodule